def summarize_logs(lines):
    from collections import Counter, defaultdict

    level_counts = defaultdict(int)
    word_counts = Counter()

    for line in lines:
        parts = line.split()
        if len(parts) < 3:
            continue

        timestamp = parts[0]
        level = parts[1]
        service = parts[2]
        message_words = parts[3:]

        if level in ("INFO", "WARN", "ERROR"):
            level_counts[level] += 1

        for word in message_words:
            word = word.lower().strip()
            if word:
                word_counts[word] += 1

    top_three = [word for word, _ in word_counts.most_common(3)]

    return {
        "levels": dict(level_counts),
        "top_words": top_three
    }
